// Golden master of the Orders HTTP API as it behaves today. Pricing is replaced by an in-process fake.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { apple: 10, pear: 30, gold: 100.5, cheap: 0.5 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const call = async (method, path, body, raw) => {
  const res = await fetch(base + path, { method, body: raw ?? (body === undefined ? undefined : JSON.stringify(body)) })
  return { status: res.status, type: res.headers.get('content-type'), body: await res.json() }
}
const post = (items) => call('POST', '/orders', { items })

test('POST /orders creates an order with 201, JSON content type and sequential string ids', async () => {
  const a = await post([{ sku: 'apple', qty: 2 }])
  assert.equal(a.status, 201)
  assert.equal(a.type, 'application/json')
  assert.deepEqual(a.body, { id: a.body.id, items: [{ sku: 'apple', qty: 2 }], total: 20 })
  assert.equal(typeof a.body.id, 'string')
  const b = await post([{ sku: 'apple', qty: 1 }])
  assert.equal(Number(b.body.id), Number(a.body.id) + 1)
})

test('POST /orders sums all lines', async () => {
  assert.equal((await post([{ sku: 'apple', qty: 2 }, { sku: 'pear', qty: 1 }])).body.total, 50)
})

test('POST /orders gives no discount at exactly 100', async () => {
  assert.equal((await post([{ sku: 'apple', qty: 10 }])).body.total, 100)
})

test('POST /orders gives 10% off above 100', async () => {
  assert.equal((await post([{ sku: 'apple', qty: 11 }])).body.total, 99)
})

test('POST /orders floors the total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — total is truncated to whole euros, not rounded
  assert.equal((await post([{ sku: 'cheap', qty: 3 }])).body.total, 1)
  assert.equal((await post([{ sku: 'gold', qty: 1 }])).body.total, 90) // 100.5 - 10.05 = 90.45
})

test('POST /orders accepts negative quantities', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — qty is not validated
  assert.equal((await post([{ sku: 'apple', qty: -1 }])).body.total, -10)
})

test('POST /orders with an unpriced sku returns total null', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — NaN total serialises to null, still 201
  const r = await post([{ sku: 'unknown', qty: 1 }])
  assert.equal(r.status, 201)
  assert.equal(r.body.total, null)
})

test('POST /orders rejects missing, empty and non-array items with 400', async () => {
  for (const body of [{}, { items: [] }, { items: 'apple' }, { items: {} }]) {
    assert.deepEqual(await call('POST', '/orders', body).then(({ status, body }) => ({ status, body })), { status: 400, body: { error: 'items required' } })
  }
})

test('POST /orders rejects invalid JSON with 400, and an empty body too', async () => {
  assert.deepEqual((await call('POST', '/orders', undefined, '{nope')).body, { error: 'items required' })
  assert.equal((await call('POST', '/orders', undefined, '{nope')).status, 400)
  assert.equal((await call('POST', '/orders')).status, 400)
  assert.equal((await call('POST', '/orders', undefined, 'null')).status, 400)
})

test('GET /orders/:id returns a previously created order', async () => {
  const created = (await post([{ sku: 'pear', qty: 1 }])).body
  const r = await call('GET', `/orders/${created.id}`)
  assert.equal(r.status, 200)
  assert.equal(r.type, 'application/json')
  assert.deepEqual(r.body, created)
})

test('GET /orders/:id for an unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is reported with status 200, not 404
  const r = await call('GET', '/orders/does-not-exist')
  assert.equal(r.status, 200)
  assert.deepEqual(r.body, { error: 'not found' })
})

test('unrouted requests answer 404 {error:"no route"}', async () => {
  for (const [m, p] of [['GET', '/orders'], ['GET', '/'], ['GET', '/nope'], ['DELETE', '/orders/1'], ['PUT', '/orders/1'], ['POST', '/orders/1'], ['GET', '/orders/1/extra'], ['GET', '/orders/']]) {
    const r = await call(m, p)
    assert.equal(r.status, 404, `${m} ${p}`)
    assert.deepEqual(r.body, { error: 'no route' })
    assert.equal(r.type, 'application/json')
  }
})

test('a trailing query string does not affect routing', async () => {
  assert.equal((await call('GET', '/orders/does-not-exist?x=1')).body.error, 'not found')
})
EOF
